                        ForEach(0..<trailingItems.count, id: \.self) { i in
                            DynamicNodeView(node: trailingItems[i], dispatch: dispatch)
                        }
                    }
                }
            }
        }


case "textinput":
    let value = node.props["value"] as? String ?? ""
        let placeholder = node.props["placeholder"] as? String ?? ""
        let onChangeStr = node.props["on_change"] as? String ?? ""
        DynamicTextInputWrapper(value: value, placeholder: placeholder, onChangeAction: onChangeStr, dispatch: dispatch)


case "image":
    let src = node.props["src"] as? String ?? ""
        let size = node.props["size"] as? Int ?? 0
        let w = node.props["width"] as? Int ?? size
        let h = node.props["height"] as? Int ?? (size > 0 ? size : 180)
        let radius = CGFloat(node.props["corner_radius"] as? Int ?? 0)
        let mode = node.props["content_mode"] as? String ?? "cover"
        let opacity = Double(node.props["opacity"] as? Int ?? 100) / 100.0
        let isContain = (mode == "contain" || mode == "fit")
    
        if src.hasPrefix("http://") || src.hasPrefix("https://"), let url = URL(string: src) {
            AsyncImage(url: url) { phase in
                switch phase {
                case .success(let image):
                    if isContain { image.resizable().scaledToFit() }
                    else { image.resizable().scaledToFill() }
                default:
                    RoundedRectangle(cornerRadius: radius, style: .continuous)
                        .fill(Color.secondary.opacity(0.14))
                        .overlay(ProgressView())
                }
            }
            .frame(width: w > 0 ? CGFloat(w) : nil, height: CGFloat(h))
            .frame(maxWidth: w > 0 ? nil : .infinity)
            .clipped()
            .clipShape(RoundedRectangle(cornerRadius: radius, style: .continuous))
            .opacity(opacity)
        } else {
            let cleanName = ((src as NSString).lastPathComponent as NSString).deletingPathExtension
            if UIImage(named: cleanName) != nil {
                Group {
                    if isContain { Image(cleanName).resizable().scaledToFit() }
                    else { Image(cleanName).resizable().scaledToFill() }
                }
                .frame(width: w > 0 ? CGFloat(w) : nil, height: CGFloat(h))
                .frame(maxWidth: w > 0 ? nil : .infinity)
                .clipped()
                .clipShape(RoundedRectangle(cornerRadius: radius, style: .continuous))
                .opacity(opacity)
            } else if let devUrl = URL(string: "http://127.0.0.1:5824/" + src.replacingOccurrences(of: "./", with: "").trimmingCharacters(in: CharacterSet(charactersIn: "/"))) {
                AsyncImage(url: devUrl) { phase in
                    if case .success(let image) = phase {
                        if isContain { image.resizable().scaledToFit() } else { image.resizable().scaledToFill() }
                    } else {
                        RoundedRectangle(cornerRadius: radius, style: .continuous).fill(Color.secondary.opacity(0.14))
                    }
                }
                .frame(width: w > 0 ? CGFloat(w) : nil, height: CGFloat(h))
                .frame(maxWidth: w > 0 ? nil : .infinity)
                .clipped()
                .clipShape(RoundedRectangle(cornerRadius: radius, style: .continuous))
                .opacity(opacity)
            }
        }


case "toolbartop":
    ForEach(0..<node.children.count, id: \.self) { i in DynamicNodeView(node: node.children[i], dispatch: dispatch) }


case "section":
    let headerStr = (node.props["header"] as? String) ?? (node.props["title"] as? String) ?? ""
        let footerStr = node.props["footer"] as? String ?? ""
        let isProminent = node.props["prominent"] as? Bool ?? false
        let headerNode = node.children.first { $0.name == "section_header" }?.children.first
        let footerNode = node.children.first { $0.name == "section_footer" }?.children.first
        let bodyChildren = node.children.filter { $0.name != "section_header" && $0.name != "section_footer" }
    
        Section {
            ForEach(0..<bodyChildren.count, id: \.self) { i in
                let child = bodyChildren[i]
                let delAction = child.props["on_delete"] as? String ?? ""
                let rowBgName = child.props["background"] as? String ?? ""
                let rowBgGrad = child.props["background_gradient"] as? [String: Any]
                let hasRowBg = !rowBgName.isEmpty || rowBgGrad != nil
                let cleanChild = hasRowBg
                    ? DynamicUINode(
                        name: child.name,
                        props: child.props.filter { $0.key != "background" && $0.key != "background_gradient" },
                        children: child.children
                    )
                    : child
                if !delAction.isEmpty {
                    DynamicNodeView(node: cleanChild, dispatch: dispatch)
                        .applyListRowBackground(node: child)
                        .swipeActions(edge: .trailing, allowsFullSwipe: true) {
                            Button(role: .destructive) {
                                dispatch(delAction, nil)
                            } label: {
                                Label("Delete", systemImage: "trash")
                            }
                        }
                } else {
                    DynamicNodeView(node: cleanChild, dispatch: dispatch)
                        .applyListRowBackground(node: child)
                }
            }
        } header: {
            if let headerNode = headerNode {
                DynamicNodeView(node: headerNode, dispatch: dispatch)
            } else if !headerStr.isEmpty {
                Text(headerStr)
            }
        } footer: {
            if let footerNode = footerNode {
                DynamicNodeView(node: footerNode, dispatch: dispatch)
            } else if !footerStr.isEmpty {
                Text(footerStr)
            }
        }
        .headerProminence(isProminent ? .increased : .standard)


case "grid":
    let cols = max(1, node.props["columns"] as? Int ?? 2)
        let spacing = CGFloat(node.props["spacing"] as? Int ?? 12)
        let headerStr = node.props["header"] as? String ?? ""
        let footerStr = node.props["footer"] as? String ?? ""
        let headerNode = node.children.first { $0.name == "section_header" }?.children.first
        let footerNode = node.children.first { $0.name == "section_footer" }?.children.first
        let bodyChildren = node.children.filter { $0.name != "section_header" && $0.name != "section_footer" }
        let gridCols = Array(repeating: GridItem(.flexible(), spacing: spacing), count: cols)
    
        VStack(alignment: .leading, spacing: 6) {
            if let headerNode = headerNode {
                DynamicNodeView(node: headerNode, dispatch: dispatch)
                    .padding(.horizontal, 4)
            } else if !headerStr.isEmpty {
                Text(headerStr.uppercased())
                    .font(.footnote)
                    .foregroundStyle(Color.secondary)
                    .padding(.horizontal, 4)
            }
            LazyVGrid(columns: gridCols, spacing: spacing) {
                ForEach(0..<bodyChildren.count, id: \.self) { i in
                    DynamicNodeView(node: bodyChildren[i], dispatch: dispatch)
                }
            }
            if let footerNode = footerNode {
                DynamicNodeView(node: footerNode, dispatch: dispatch)
                    .padding(.horizontal, 4)
            } else if !footerStr.isEmpty {
                Text(footerStr)
                    .font(.footnote)
                    .foregroundStyle(Color.secondary)
                    .padding(.horizontal, 4)
            }
        }


case "spacer":
    let size = node.props["size"] as? Int ?? 0
        if size > 0 {
            Spacer().frame(width: CGFloat(size), height: CGFloat(size))
        } else {
            Spacer(minLength: 0)
        }

    default:
        EmptyView()
    }
}
